(1177, '打破冷场', 'break the ice', '习语', '社交', 2, 'A small joke can break the ice.', '一个小笑话可以打破冷场。', 'verb phrase', true, false, '/breɪk ði aɪs/', null),
(1178, '轻而易举的事', 'a piece of cake', '习语', '难易', 2, 'The test was a piece of cake.', '这次考试轻而易举。', 'noun phrase', true, false, '/ə pis əv keɪk/', null),
(1179, '身体不舒服', 'under the weather', '习语', '健康', 2, 'I am feeling under the weather today.', '我今天感觉身体不舒服。', 'adjective phrase', true, false, '/ˈʌndər ðə ˈwɛðər/', null),
(1180, '难得一次', 'once in a blue moon', '习语', '频率', 3, 'We eat out once in a blue moon.', '我们很少出去吃饭。', 'adverb phrase', true, false, '/wʌns ɪn ə blu mun/', null),
(1181, '泄露秘密', 'spill the beans', '习语', '沟通', 3, 'Do not spill the beans about the party.', '别泄露聚会的秘密。', 'verb phrase', true, false, '/spɪl ðə binz/', null),
(1182, '无意中泄露秘密', 'let the cat out of the bag', '习语', '沟通', 3, 'I accidentally let the cat out of the bag.', '我不小心说漏了嘴。', 'verb phrase', true, false, '/lɛt ðə kæt aʊt əv ðə bæɡ/', null),
(1183, '说到点子上', 'hit the nail on the head', '习语', '沟通', 3, 'You hit the nail on the head with that comment.', '你的那句评论说到点子上了。', 'verb phrase', true, false, '/hɪt ðə neɪl ɑn ðə hɛd/', null),
(1184, '贵得离谱', 'cost an arm and a leg', '习语', '金钱', 3, 'That car must cost an arm and a leg.', '那辆车一定贵得离谱。', 'verb phrase', true, false, '/kɔst ən ɑrm ænd ə lɛɡ/', null),
(1185, '接下来该你行动了', 'the ball is in your court', '习语', '决定', 3, 'I sent the offer; now the ball is in your court.', '我发出了报价，现在该你决定了。', 'clause', true, false, '/ðə bɔl ɪz ɪn jʊr kɔrt/', null),
(1186, '意见一致；理解一致', 'on the same page', '习语', '合作', 2, 'Let us make sure we are on the same page.', '我们确认一下彼此的理解是否一致。', 'adjective phrase', true, false, '/ɑn ðə seɪm peɪdʒ/', null),
(1187, '看法一致', 'see eye to eye', '习语', '合作', 3, 'We do not always see eye to eye.', '我们的看法并非总是一致。', 'verb phrase', true, false, '/si aɪ tu aɪ/', null),
(1188, '临阵退缩', 'get cold feet', '习语', '情绪', 3, 'Do not get cold feet before the interview.', '面试前别打退堂鼓。', 'verb phrase', true, false, '/ɡɛt koʊld fit/', null),
(1189, '帮某人一把', 'give someone a hand', '习语', '帮助', 2, 'It feels good to give someone a hand.', '帮别人一把让人感觉很好。', 'verb phrase', true, false, '/ɡɪv ˈsʌmˌwʌn ə hænd/', null),
(1190, '留意；照看', 'keep an eye on', '习语', '照护', 2, 'Please keep an eye on my bag.', '请帮我照看一下包。', 'verb phrase', true, false, '/kip ən aɪ ɑn/', null),
(1191, '祈求好运', 'keep your fingers crossed', '习语', '希望', 3, 'Keep your fingers crossed for my exam.', '祝我考试好运吧。', 'verb phrase', true, false, '/kip jʊr ˈfɪŋɡərz krɔst/', null),
(1192, '坚持住', 'hang in there', '习语', '鼓励', 2, 'Hang in there; help is coming.', '坚持住，马上就有人来帮忙了。', 'verb phrase', true, false, '/hæŋ ɪn ðɛr/', null),
(1193, '振作起来', 'pull yourself together', '习语', '鼓励', 3, 'Take a breath and pull yourself together.', '深呼吸，振作起来。', 'verb phrase', true, false, '/pʊl jʊrˈsɛlf təˈɡɛðər/', null),
(1194, '掌握……的窍门', 'get the hang of', '习语', '学习', 2, 'You will get the hang of this game soon.', '你很快就会掌握这个游戏的窍门。', 'verb phrase', true, false, '/ɡɛt ðə hæŋ əv/', null),
(1195, '熟悉做事的方法', 'learn the ropes', '习语', '工作', 3, 'It takes time to learn the ropes at a new job.', '熟悉新工作的门道需要时间。', 'verb phrase', true, false, '/lɜrn ðə roʊps/', null),
(1196, '偷工减料；图省事', 'cut corners', '习语', '工作', 3, 'We cannot cut corners on safety.', '我们不能在安全方面偷工减料。', 'verb phrase', true, false, '/kʌt ˈkɔrnərz/', null),
(1197, '付出额外努力', 'go the extra mile', '习语', '工作', 3, 'She is willing to go the extra mile for customers.', '她愿意为顾客付出额外的努力。', 'verb phrase', true, false, '/ɡoʊ ði ˈɛkstrə maɪl/', null),
(1198, '回到起点；从头再来', 'back to square one', '习语', '进展', 3, 'The plan failed, so we are back to square one.', '计划失败了，我们得从头再来。', 'adverb phrase', true, false, '/bæk tə skwɛr wʌn/', null),
(1199, '重新设计；重新想办法', 'back to the drawing board', '习语', '进展', 3, 'This idea failed; it is back to the drawing board.', '这个想法失败了，得重新想办法。', 'adverb phrase', true, false, '/bæk tə ðə ˈdrɔɪŋ bɔrd/', null),
(1200, '结束当天的工作', 'call it a day', '习语', '工作', 2, 'We have done enough; let us call it a day.', '我们做得够多了，今天就到这里吧。', 'verb phrase', true, false, '/kɔl ɪt ə deɪ/', null)
