(1201, '熬夜工作或学习', 'burn the midnight oil', '习语', '工作', 3, 'I had to burn the midnight oil to finish the report.', '为了完成报告，我不得不熬夜。', 'verb phrase', true, false, '/bɜrn ðə ˈmɪdˌnaɪt ɔɪl/', null),
(1202, '精疲力竭；过度劳累', 'burn out', '习语', '健康', 2, 'You may burn out if you never rest.', '如果从不休息，你可能会累垮。', 'phrasal verb', true, false, '/bɜrn aʊt/', null),
(1203, '忙个不停', 'on the go', '习语', '生活', 2, 'I have been on the go all day.', '我一整天都忙个不停。', 'adjective phrase', true, false, '/ɑn ðə ɡoʊ/', null),
(1204, '从长远来看', 'in the long run', '习语', '时间', 2, 'This will save money in the long run.', '从长远来看，这样会省钱。', 'adverb phrase', true, false, '/ɪn ðə lɔŋ rʌn/', null),
(1205, '在最后一刻', 'at the last minute', '习语', '时间', 2, 'He canceled at the last minute.', '他在最后一刻取消了。', 'adverb phrase', true, false, '/æt ðə læst ˈmɪnət/', null),
(1206, '迟做总比不做好', 'better late than never', '习语', '时间', 3, 'You finally replied; better late than never.', '你终于回复了，迟回总比不回好。', 'proverb', true, false, '/ˈbɛtər leɪt ðæn ˈnɛvər/', null),
(1207, '时光飞逝', 'time flies', '习语', '时间', 2, 'Time flies when you are having fun.', '玩得开心时，时间过得飞快。', 'clause', true, false, '/taɪm flaɪz/', null),
(1208, '全天候；昼夜不停', 'around the clock', '习语', '时间', 3, 'The team worked around the clock.', '团队昼夜不停地工作。', 'adverb phrase', true, false, '/əˈraʊnd ðə klɑk/', null),
(1209, '很快', 'in no time', '习语', '时间', 2, 'You will feel better in no time.', '你很快就会好起来。', 'adverb phrase', true, false, '/ɪn noʊ taɪm/', null),
(1210, '到目前为止一切顺利', 'so far so good', '习语', '进展', 2, 'We have started the project; so far so good.', '我们已经开始这个项目，目前一切顺利。', 'clause', true, false, '/soʊ fɑr soʊ ɡʊd/', null),
(1211, '出乎意料地；突然', 'out of the blue', '习语', '意外', 3, 'She called me out of the blue.', '她突然给我打了电话。', 'adverb phrase', true, false, '/aʊt əv ðə blu/', null),
(1212, '因祸得福的事', 'a blessing in disguise', '习语', '得失', 3, 'Missing that train was a blessing in disguise.', '错过那班火车反而成了一件好事。', 'noun phrase', true, false, '/ə ˈblɛsɪŋ ɪn dɪsˈɡaɪz/', null),
(1213, '黑暗中总有一线光明', 'every cloud has a silver lining', '习语', '希望', 4, 'Remember, every cloud has a silver lining.', '记住，困境中总有一线希望。', 'proverb', true, false, '/ˈɛvri klaʊd hæz ə ˈsɪlvər ˈlaɪnɪŋ/', null),
(1214, '两全其美', 'the best of both worlds', '习语', '选择', 3, 'Working near home gives me the best of both worlds.', '在家附近工作让我两全其美。', 'noun phrase', true, false, '/ðə bɛst əv boʊθ wɜrldz/', null),
(1215, '双赢局面', 'a win-win situation', '习语', '合作', 2, 'Sharing the office is a win-win situation.', '共用办公室是个双赢的安排。', 'noun phrase', true, false, '/ə ˌwɪn ˈwɪn ˌsɪtʃuˈeɪʃən/', null),
(1216, '一举两得', 'kill two birds with one stone', '习语', '效率', 3, 'Walking to work lets me kill two birds with one stone: travel and exercise.', '步行上班让我一举两得：既通勤又锻炼。', 'verb phrase', true, false, '/kɪl tu bɜrdz wɪð wʌn stoʊn/', null),
(1217, '孤注一掷', 'put all your eggs in one basket', '习语', '风险', 3, 'Do not put all your eggs in one basket.', '别把所有希望都押在一件事上。', 'verb phrase', true, false, '/pʊt ɔl jʊr ɛɡz ɪn wʌn ˈbæskət/', null),
(1218, '谨慎行事', 'play it safe', '习语', '风险', 2, 'Let us play it safe and leave early.', '我们稳妥一点，早点出发吧。', 'verb phrase', true, false, '/pleɪ ɪt seɪf/', null),
(1219, '改天再约', 'take a rain check', '习语', '社交', 3, 'Can I take a rain check on dinner?', '晚饭能改天再约吗？', 'verb phrase', true, false, '/teɪk ə reɪn tʃɛk/', null),
(1220, '持观望态度；不表态', 'sit on the fence', '习语', '决定', 3, 'You cannot sit on the fence forever.', '你不能一直不表态。', 'verb phrase', true, false, '/sɪt ɑn ðə fɛns/', null),
(1221, '犹豫不决', 'on the fence', '习语', '决定', 3, 'I am still on the fence about moving.', '对于搬家，我还在犹豫。', 'adjective phrase', true, false, '/ɑn ðə fɛns/', null),
(1222, '尚未确定', 'up in the air', '习语', '决定', 2, 'Our travel plans are still up in the air.', '我们的旅行计划还没定下来。', 'adjective phrase', true, false, '/ʌp ɪn ði ɛr/', null),
(1223, '简而言之', 'in a nutshell', '习语', '沟通', 3, 'In a nutshell, we need more time.', '简而言之，我们需要更多时间。', 'adverb phrase', true, false, '/ɪn ə ˈnʌtˌʃɛl/', null),
(1224, '长话短说', 'to make a long story short', '习语', '沟通', 3, 'To make a long story short, we missed the bus.', '长话短说，我们错过了公交车。', 'discourse phrase', true, false, '/tə meɪk ə lɔŋ ˈstɔri ʃɔrt/', null),
(1225, '拐弯抹角', 'beat around the bush', '习语', '沟通', 3, 'Do not beat around the bush; tell me what happened.', '别拐弯抹角，告诉我发生了什么。', 'verb phrase', true, false, '/bit əˈraʊnd ðə bʊʃ/', null),
(1226, '直奔主题', 'get straight to the point', '习语', '沟通', 2, 'Let me get straight to the point.', '让我直奔主题吧。', 'verb phrase', true, false, '/ɡɛt streɪt tə ðə pɔɪnt/', null),
(1227, '领会言外之意', 'read between the lines', '习语', '沟通', 3, 'Read between the lines of her message.', '体会一下她消息里的言外之意。', 'verb phrase', true, false, '/rid bɪˈtwin ðə laɪnz/', null),
(1228, '对某事半信半疑', 'take it with a grain of salt', '习语', '判断', 3, 'That story sounds strange; take it with a grain of salt.', '那个故事听着奇怪，别全信。', 'verb phrase', true, false, '/teɪk ɪt wɪð ə ɡreɪn əv sɔlt/', null),
(1229, '说起来容易做起来难', 'easier said than done', '习语', '难易', 2, 'Saving money is easier said than done.', '存钱说起来容易做起来难。', 'adjective phrase', true, false, '/ˈiziər sɛd ðæn dʌn/', null),
(1230, '行动胜于言辞', 'actions speak louder than words', '习语', '行动', 3, 'Show us you care; actions speak louder than words.', '用行动证明你在乎，行动胜于言辞。', 'proverb', true, false, '/ˈækʃənz spik ˈlaʊdər ðæn wɜrdz/', null),
(1231, '熟能生巧', 'practice makes perfect', '习语', '学习', 2, 'Keep practicing; practice makes perfect.', '继续练习，熟能生巧。', 'proverb', true, false, '/ˈpræktɪs meɪks ˈpɜrfɪkt/', null),
(1232, '不劳无获', 'no pain, no gain', '习语', '努力', 3, 'Learning takes effort: no pain, no gain.', '学习需要努力，不劳无获。', 'proverb', true, false, '/noʊ peɪn noʊ ɡeɪn/', null),
(1233, '入乡随俗（谚语缩略形式）', 'when in Rome', '习语', '文化', 3, 'We followed the local dining customs; when in Rome!', '我们遵循了当地的用餐习惯，入乡随俗嘛！', 'proverb fragment', true, false, '/wɛn ɪn roʊm/', null),
(1234, '小心驶得万年船', 'better safe than sorry', '习语', '风险', 2, 'Take an umbrella; better safe than sorry.', '带把伞吧，有备无患。', 'proverb', true, false, '/ˈbɛtər seɪf ðæn ˈsɑri/', null),
(1235, '早起的鸟儿有虫吃', 'the early bird catches the worm', '习语', '机会', 3, 'Apply early; the early bird catches the worm.', '早点申请，早行动的人先得到机会。', 'proverb', true, false, '/ði ˈɜrli bɜrd ˈkætʃɪz ðə wɜrm/', null),
(1236, '不要以貌取人', 'do not judge a book by its cover', '习语', '判断', 3, 'Do not judge a book by its cover; this small restaurant is excellent.', '别以貌取人，这家小餐馆很棒。', 'proverb', true, false, '/du nɑt dʒʌdʒ ə bʊk baɪ ɪts ˈkʌvər/', null),
